const KEY='setmate-v1';
const machineCatalog=[{"id":"lat-pulldown","name":"Lat pulldown","group":"Back","brand":"Other"},{"id":"chest-press","name":"Chest press","group":"Chest","brand":"Other"},{"id":"leg-press","name":"Seated leg press","group":"Legs","brand":"Other"},{"id":"leg-curl","name":"Seated leg curl","group":"Legs","brand":"Other"},{"id":"biceps-curl","name":"Biceps curl","group":"Arms","brand":"Other"},{"id":"shoulder-press","name":"Shoulder press","group":"Shoulders","brand":"Other"},{"id":"outer-thigh","name":"Outer thigh","group":"Legs","brand":"Other"},{"id":"leg-extension","name":"Leg extension","group":"Legs","brand":"Other"},{"id":"hoist-inner-thigh","name":"Inner thigh","group":"Legs","brand":"HOIST"},{"id":"hoist-mid-row","name":"Mid row","group":"Back","brand":"HOIST"},{"id":"hoist-biceps-curl","name":"Biceps curl","group":"Arms","brand":"HOIST"},{"id":"rotary-calf","name":"Rotary calf","group":"Legs","brand":"Other"},{"id":"hoist-outer-thigh","name":"Outer thigh","group":"Legs","brand":"HOIST"},{"id":"low-back","name":"Low back","group":"Back","brand":"Other"},{"id":"hoist-abs","name":"Abs","group":"Core","brand":"HOIST"},{"id":"glute-master","name":"Glute master","group":"Legs","brand":"Other"},{"id":"hoist-triceps","name":"Triceps","group":"Arms","brand":"HOIST"},{"id":"hoist-pec-fly","name":"Pec fly","group":"Chest","brand":"HOIST"},{"id":"hoist-lat-pulldown","name":"Lat pulldown","group":"Back","brand":"HOIST"}];
const defaultNotebook=window.SETMATE_DEFAULT;
const initial={person:'Justin',unit:'lb',machines:structuredClone(defaultNotebook.machines),sets:structuredClone(defaultNotebook.sets),defaultsVersion:1};
let state,storageError='';try{state=JSON.parse(localStorage.getItem(KEY))||structuredClone(initial);if(!Array.isArray(state.machines)||!Array.isArray(state.sets))throw Error('Invalid saved data');}catch(e){state=structuredClone(initial);storageError='Your saved data could not be loaded. Please keep this window open; saving is disabled to protect any existing data.';}
if(!storageError){const migrated={...state,person:state.person==='You'?'Justin':state.person,machines:state.machines.map(m=>({...m,name:m.id==='leg-press'&&m.name==='Leg press'?'Seated leg press':m.id==='leg-curl'&&m.name==='Leg curl'?'Seated leg curl':m.name,brand:m.brand||'Other'})),sets:state.sets.map(s=>({...s,person:s.person==='You'?'Justin':s.person}))};try{localStorage.setItem(KEY,JSON.stringify(migrated));state=migrated;}catch(e){storageError='Could not update local storage. Your existing records have been preserved.';}}
if(!storageError){const machines=[...state.machines];for(const machine of machineCatalog){if(machines.some(m=>m.id===machine.id||m.id==='catalog-'+machine.id))continue;if(!machines.some(m=>m.name.toLowerCase()===machine.name.toLowerCase()&&(m.brand||'Other')===machine.brand)){const id=machines.some(m=>m.id===machine.id)?'catalog-'+machine.id:machine.id;if(!machines.some(m=>m.id===id))machines.push({...machine,id});}}try{localStorage.setItem(KEY,JSON.stringify({...state,machines}));state={...state,machines};}catch(e){storageError='Could not update the machine list. Your existing records have been preserved.';}}
let showHidden=false;
let view='list',selected=null,query='',group='All',weight='',reps='',offlineReady=false;
const root=document.querySelector('#app');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const localDay=t=>{const d=new Date(t);return `${d.getFullYear()}-${d.getMonth()}-${d.getDate()}`;};
const isToday=t=>localDay(t)===localDay(Date.now());
function save(next){if(storageError){toast('Storage unavailable. Your set was not saved.');return false;}try{localStorage.setItem(KEY,JSON.stringify(next));state=next;return true;}catch(e){toast('Could not save. Check your device storage and try again.');return false;}}
function toast(t){const el=document.querySelector('#toast');el.textContent=t;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),3200);}
function machineSets(){return state.sets.filter(s=>s.machine===selected&&s.person===state.person);}
function format(s){return `${s.weight} ${s.unit}${s.reps!=null?' × '+s.reps+' reps':''}`;}
function dateLabel(t){if(isToday(t))return 'Today';return new Date(t).toLocaleDateString(undefined,{month:'short',day:'numeric',year:new Date(t).getFullYear()!==new Date().getFullYear()?'numeric':undefined});}
function header(){return `<header><div class="brand"><span class="mark" aria-hidden="true">Ⅱ</span>setmate<span style="color:var(--lime)">.</span></div><button class="icon-button" data-action="info" aria-label="App and installation information">ⓘ</button></header>`;}
function people(){return `<div class="people" aria-label="Workout profile">${['Justin','Mabel'].map(p=>`<button data-person="${p}" class="${state.person===p?'active':''}" aria-pressed="${state.person===p}"><img class="panda" src="panda-${p.toLowerCase()}.png" alt="">${p}</button>`).join('')}</div>`;}
function footer(){return `<div class="foot"><span class="dot"></span><span>${offlineReady?'Ready offline · Saved on this device':'Saved on this device'}</span></div>`;}
function render(){if(view==='list')renderList();else if(view==='detail')renderDetail();else if(view==='add')renderAdd();else if(view==='edit')renderEdit();else renderInfo();}

function muscleGroup(machine){
  const name=machine.name.toLowerCase();let target;
  if(/calf/.test(name))target='calves';
  else if(/leg curl|hamstring/.test(name))target='hamstrings';
  else if(/inner thigh|adduct/.test(name))target='inner thighs';
  else if(/outer thigh|abduct/.test(name))target='outer hips';
  else if(/glute/.test(name))target='glutes';
  else if(/leg press|leg extension|quad/.test(name))target='quads';
  else if(/tricep/.test(name))target='triceps';
  else if(/bicep/.test(name))target='biceps';
  else if(/low back|lower back/.test(name))target='lower back';
  else if(/pulldown|pull.down|lat pull/.test(name))target='lats';
  else if(/row/.test(name))target='upper back';
  else target=({Chest:'chest',Back:'upper back',Shoulders:'shoulders',Arms:'biceps',Core:'abs',Legs:'quads'})[machine.group]||'full body';
  return target;
}
function muscleIcon(machine){
  const target=muscleGroup(machine);
  const rear=['calves','hamstrings','glutes','triceps','lower back','lats','upper back'].includes(target);
  const regions={
    chest:'M23 23Q27 21 31 23V31Q26 33 23 29ZM33 23Q37 21 41 23V29Q38 33 33 31Z',
    shoulders:'M21 21Q17 21 16 27L20 30L23 24ZM43 21Q47 21 48 27L44 30L41 24Z',
    biceps:'M16 29L20 31L18 39L14 38ZM48 29L44 31L46 39L50 38Z',
    triceps:'M16 28L20 30L18 40L14 39ZM48 28L44 30L46 40L50 39Z',
    abs:'M27 32H37L36 46H28Z',
    'upper back':'M23 23L31 21V35L27 33ZM33 21L41 23L37 33L33 35Z',
    lats:'M22 26L29 31L29 42L24 38ZM42 26L35 31L35 42L40 38Z',
    'lower back':'M26 36L31 39V46H26ZM38 36L33 39V46H38Z',
    quads:'M23 51L30 52L28 65L23 64ZM41 51L34 52L36 65L41 64Z',
    hamstrings:'M23 52L30 52L28 65L23 64ZM41 52L34 52L36 65L41 64Z',
    glutes:'M23 45Q27 43 31 46V52Q26 55 23 52ZM33 46Q37 43 41 45V52Q38 55 33 52Z',
    'inner thighs':'M28 51L31 51L29 64L27 62ZM36 51L33 51L35 64L37 62Z',
    'outer hips':'M23 44L27 45L26 56L23 55ZM41 44L37 45L38 56L41 55Z',
    calves:'M23 67L28 67L26 77L23 76ZM41 67L36 67L38 77L41 76Z'
  };
  return '<svg class="muscle-icon" viewBox="0 0 64 88" aria-hidden="true" focusable="false"><title>'+esc(target)+' · '+(rear?'back':'front')+' view</title><g class="body-shadow"><circle cx="32" cy="10" r="6"/><path d="M28 17H36L37 20L44 22Q48 23 49 29L53 46Q54 49 51 50Q48 51 47 47L43 33L41 39L42 48L41 65L43 79Q43 82 40 82H37Q35 82 35 79L32 59L29 79Q29 82 27 82H24Q21 82 21 79L23 65L22 48L23 39L21 33L17 47Q16 51 13 50Q10 49 11 46L15 29Q16 23 20 22L27 20Z"/></g><path class="muscle-highlight" d="'+(regions[target]||'')+'"/>'+(rear?'<path class="body-guide" d="M32 22V43M32 46V52"/>':'<path class="body-guide" d="M32 24V30"/>')+'</svg>';
}

function matchesBodyFilter(m){if(group==='All')return true;const isCore=m.group==='Core'||/\babs?\b|abdominal/i.test(m.name);if(isCore)return true;if(group==='Upper body')return ['Chest','Back','Shoulders','Arms'].includes(m.group);if(group==='Lower body')return m.group==='Legs';return false;}
function listMarkup(){const filtered=state.machines.filter(m=>(showHidden||!m.hidden)&&matchesBodyFilter(m)&&m.name.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>lastUsed(a)-lastUsed(b)||muscleGroup(a).localeCompare(muscleGroup(b))||a.name.localeCompare(b.name));return `<div class="section-row"><h2>Your machines</h2><span class="count">${filtered.length} machines</span></div><p class="hint" style="margin:0 0 15px">Muscles trained longest ago first · ${esc(state.person)}</p><div class="machine-list">${filtered.map(m=>{const last=state.sets.filter(s=>s.machine===m.id&&s.person===state.person).sort((a,b)=>a.time.localeCompare(b.time)).at(-1);return `<button class="machine" data-machine="${esc(m.id)}"><span class="machine-code" aria-hidden="true">${muscleIcon(m)}</span><span class="machine-content"><strong>${esc(m.name)} ${m.hidden?'<span class="brand-tag">Hidden</span>':''} ${m.brand==='HOIST'?'<img class="hoist-logo" src="hoist-logo.png?v=9" alt="HOIST">':''}</strong><small>${esc(muscleGroup(m))} · ${lastUsed(m)?'Last trained '+esc(dateLabel(lastUsed(m))):'Not trained yet'}</small><small class="machine-last-set">${last?'Last set: '+esc(format(last)):'No sets on this machine yet'}</small></span><span class="chevron" aria-hidden="true">›</span></button>`;}).join('')||'<div class="empty">No machines found.<br>Try another filter or add a machine.</div>'}</div>`;}
function todayMachines(){const ids=[...new Set(state.sets.filter(s=>s.person===state.person&&isToday(s.time)).sort((a,b)=>a.time.localeCompare(b.time)).map(s=>s.machine))];return ids.map(id=>state.machines.find(m=>m.id===id)).filter(Boolean);}
function todayMarkup(){const machines=todayMachines();return `<section class="today-summary" aria-label="Machines used today by ${esc(state.person)}"><div class="today-summary-heading"><strong>Today</strong><span>${machines.length} ${machines.length===1?'machine':'machines'}</span></div>${machines.length?`<div class="today-icons">${machines.map(m=>`<button class="today-machine" data-machine="${esc(m.id)}" aria-label="${esc(m.name)}${m.brand==='HOIST'?' (HOIST)':''} · completed today" title="${esc(m.name)}${m.brand==='HOIST'?' (HOIST)':''}">${muscleIcon(m)}<span class="today-check" aria-hidden="true">✓</span></button>`).join('')}</div>`:'<span class="today-none">No machines yet</span>'}</section>`;}
function renderList(){root.innerHTML=header()+`<div class="eyebrow">Your workout, at a glance</div><h1>Let’s get a set in.</h1>`+people()+todayMarkup()+`${storageError?`<p class="error">${esc(storageError)}</p>`:''}<div class="search-wrap"><span aria-hidden="true">⌕</span><input id="search" type="search" placeholder="Find a machine" aria-label="Filter machines by name" value="${esc(query)}"><button id="clear-search" class="clear-search" type="button" data-action="clear-search" aria-label="Clear machine filter" ${query?'':'hidden'}>×</button></div><div class="chips" aria-label="Filter by body area">${['All','Upper body','Lower body'].map(g=>`<button data-group="${esc(g)}" class="${group===g?'active':''}" aria-pressed="${group===g}">${esc(g)}</button>`).join('')}</div><button class="hidden-toggle" data-action="toggle-hidden" aria-pressed="${showHidden}">${showHidden?'Hide hidden machines':'Show hidden machines'}</button><div id="list-results">${listMarkup()}</div><button class="add" data-action="add">＋ Add a machine</button>`+footer();}
function renderDetail(){const m=state.machines.find(m=>m.id===selected);const sets=machineSets().sort((a,b)=>a.time.localeCompare(b.time));const today=sets.filter(s=>isToday(s.time));const previous=sets.filter(s=>!isToday(s.time));const last=previous.at(-1);const lastSets=last?previous.filter(s=>localDay(s.time)===localDay(last.time)):[];root.innerHTML='<div class="detail-page">'+header()+`<button class="back" data-action="back">‹ All machines</button><div class="eyebrow">${esc(m.group)}${m.brand==='HOIST'?' <img class="hoist-logo" src="hoist-logo.png?v=9" alt="HOIST">':''}</div><h1>${esc(m.name)}</h1>`+people()+`<div class="last"><div class="last-label"><strong>Last workout · ${esc(state.person)}</strong><span>${last?esc(dateLabel(last.time)):''}</span></div>${last?`<div class="last-sets">${lastSets.map(s=>`<button data-repeat="${s.id}" aria-label="Use ${esc(format(s))}">${esc(format(s))}</button>`).join('')}</div><p class="hint">Tap a set to use those numbers again.</p>`:`<p class="sub" style="margin:0">No previous workout yet. Your first set starts here.</p>`}</div><form id="set-form"><div class="entry"><div class="label-row"><label for="weight">Weight</label><div class="units">${['lb','kg'].map(u=>`<button type="button" data-unit="${u}" class="${state.unit===u?'active':''}" aria-pressed="${state.unit===u}">${u}</button>`).join('')}</div></div><div class="stepper"><button type="button" data-step="weight:-5" aria-label="Decrease weight">−</button><input id="weight" name="weight" type="text" inputmode="decimal" placeholder="0" autocomplete="off" aria-label="Weight in ${state.unit}" value="${esc(weight)}" required><button type="button" data-step="weight:5" aria-label="Increase weight">＋</button></div><div class="suggestions">${suggestions(m).map(w=>`<button type="button" data-weight="${w}">${w} ${state.unit}</button>`).join('')}</div><p class="hint" id="weight-step-hint">${esc(weightStepHint(m))} Tap the number above to enter any custom weight.</p></div><div class="entry"><div class="label-row"><label for="reps">Reps <span class="optional">optional</span></label><button type="button" class="undo" data-action="clear-reps">Clear</button></div><div class="stepper"><button type="button" data-step="reps:-1" aria-label="Decrease reps by 1">−</button><input id="reps" name="reps" type="text" inputmode="numeric" placeholder="—" autocomplete="off" aria-label="Reps, optional" value="${esc(reps)}"><button type="button" data-step="reps:1" aria-label="Increase reps by 1">＋</button></div></div><div class="log-dock"><button class="primary log-button" type="submit"><span>＋ Log set for ${esc(state.person)}</span><span id="log-preview" class="log-preview">${esc(logPreview())}</span></button><span class="log-machine">${esc(m.name)}</span></div></form><section class="today"><div class="section-row"><h2>Today’s sets</h2><span class="count">${today.length} ${today.length===1?'set':'sets'}</span></div>${today.map((s,i)=>`<div class="set-row"><span class="set-num">${String(i+1).padStart(2,'0')}</span><span class="set-detail">${esc(format(s))}<br><small>${new Date(s.time).toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit'})}</small></span><button class="undo" data-remove="${s.id}" aria-label="Remove set ${i+1}">Remove</button></div>`).join('')||'<p class="sub">No sets logged today. Ready when you are.</p>'}${historyMarkup(sets)}</section><button class="add" data-action="edit-machine">Edit machine</button><button class="add" data-action="hide-machine">${m.hidden?'Show this machine again':'Hide this machine'}</button>`+footer()+'</div>';}
function renderEdit(){const m=state.machines.find(m=>m.id===selected);root.innerHTML=header()+`<button class="back" data-action="cancel-edit">‹ Back to machine</button><div class="eyebrow">Machine settings</div><h1>Edit machine.</h1><form id="edit-machine-form" class="form"><label>Machine name<input name="name" value="${esc(m.name)}" maxlength="80" required autocomplete="off"></label><label>Machine type<select name="brand"><option value="Other" ${m.brand!=='HOIST'?'selected':''}>Other</option><option value="HOIST" ${m.brand==='HOIST'?'selected':''}>HOIST</option></select></label><button class="primary" type="submit">Save changes</button><button class="add" type="button" data-action="cancel-edit">Cancel</button></form>`+footer();}
function renderAdd(){root.innerHTML=header()+`<button class="back" data-action="back">‹ All machines</button><div class="eyebrow">Make it yours</div><h1>Add a machine.</h1><form id="machine-form" class="form"><label>Machine name<input name="name" placeholder="e.g. Cable row" maxlength="80" required autocomplete="off"></label><label>Machine type<select name="brand"><option>Other</option><option>HOIST</option></select></label><label>Muscle group<select name="group">${['Legs','Chest','Back','Shoulders','Arms','Core','Other'].map(g=>`<option>${g}</option>`).join('')}</select></label><button class="primary" type="submit">Add machine</button></form>`+footer();}
function renderInfo(){root.innerHTML=header()+`<button class="back" data-action="back">‹ All machines</button><div class="eyebrow">App & data</div><h1>Your pocket log.</h1><div class="notice"><strong>Install on iPhone</strong><ol><li>Open this app’s link in Safari.</li><li>Tap Share, then <strong>Add to Home Screen</strong>.</li><li>Keep <strong>Open as Web App</strong> enabled if shown, then tap Add.</li></ol></div><div class="notice"><strong>Your workout data</strong><p>A new device starts with the 147 sets from your September notebook. Workouts you add stay on this device, and devices don’t sync.</p><p>The starting notebook is included in the public app. Your new entries are never uploaded.</p><p>Safari, the Home Screen app, and this preview can have separate storage. Log real workouts in the installed app.</p><p id="offline-info">${offlineReady?'Ready to use offline.':'Loading offline files. Keep the app open until it’s ready.'}</p></div><div class="notice"><strong>Import workouts</strong><p>Add records from a workout file without replacing your existing sets.</p><label class="import-label">Import workout file<input id="import-file" type="file" accept=".json,application/json"></label><p id="import-status" role="status"></p></div><div class="notice reset-section"><strong>Reset data</strong><p>Restore the starting notebook’s 147 sets and 19 machines. Workouts and machines you added, along with hidden-machine choices, will be removed.</p><button class="reset-button" data-action="reset-data">Reset to default data</button></div><dialog id="reset-dialog" role="alertdialog" aria-labelledby="reset-title" aria-describedby="reset-description"><h2 id="reset-title">Are you sure you want to reset?</h2><p id="reset-description">This replaces all workout data on this device with the default September notebook: 147 sets and 19 machines. Your added workouts and machines will be removed.</p><div class="dialog-actions"><button class="cancel-reset" data-action="cancel-reset" autofocus>Cancel</button><button class="confirm-reset" data-action="confirm-reset">Yes, reset data</button></div></dialog>`+footer();}
function restoreDefaults(){const fresh=structuredClone(initial);try{localStorage.setItem(KEY,JSON.stringify(fresh));state=fresh;storageError='';selected=null;weight='';reps='';query='';group='All';showHidden=false;view='info';render();toast('Default workout data restored');}catch(e){toast('Could not reset. Your saved data was kept.');}}

function logPreview(){const w=weight.trim().replace(',','.');const r=reps.trim();if(!w)return 'Enter a weight to log';return w+' '+state.unit+(r?' × '+r+' reps':' · Weight only');}
function updateLogPreview(){const label=document.querySelector('#log-preview');if(label)label.textContent=logPreview();const hint=document.querySelector('#weight-step-hint');if(hint){const m=state.machines.find(m=>m.id===selected);hint.textContent=weightStepHint(m)+' Tap the number above to enter any custom weight.';}}
function preload(){const last=machineSets().sort((a,b)=>a.time.localeCompare(b.time)).at(-1);weight=last?String(last.weight):'';reps=last&&last.reps!==null?String(last.reps):'';if(last&&last.unit!==state.unit)save({...state,unit:last.unit});}
root.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;document.querySelector('#clear-search').hidden=!query;document.querySelector('#list-results').innerHTML=listMarkup();}if(e.target.id==='weight')weight=e.target.value;if(e.target.id==='reps')reps=e.target.value;updateLogPreview();});
root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.person){if(save({...state,person:d.person})){if(view==='detail')preload();render();}}else if(d.machine){selected=d.machine;view='detail';preload();render();window.scrollTo(0,0);}else if(d.weight){weight=d.weight;document.querySelector('#weight').value=weight;}else if(d.group){group=d.group;render();}else if(d.action){if(d.action==='clear-search'){query='';document.querySelector('#search').value='';document.querySelector('#clear-search').hidden=true;document.querySelector('#list-results').innerHTML=listMarkup();document.querySelector('#search').focus();}if(d.action==='edit-machine'){view='edit';render();window.scrollTo(0,0);}if(d.action==='cancel-edit'){view='detail';render();window.scrollTo(0,0);}if(d.action==='reset-data'){document.querySelector('#reset-dialog').showModal();}if(d.action==='cancel-reset'){document.querySelector('#reset-dialog').close();}if(d.action==='confirm-reset'){restoreDefaults();}if(d.action==='toggle-hidden'){showHidden=!showHidden;render();}if(d.action==='hide-machine'){const m=state.machines.find(x=>x.id===selected);if(save({...state,machines:state.machines.map(x=>x.id===selected?{...x,hidden:!x.hidden}:x)})){view='list';render();toast(m.hidden?'Machine shown again':'Machine hidden. History kept.');}}if(d.action==='back'){view='list';render();window.scrollTo(0,0);}if(d.action==='add'){view='add';render();}if(d.action==='info'){view='info';render();}if(d.action==='clear-reps'){reps='';document.querySelector('#reps').value='';}}else if(d.unit){const next=d.unit;if(next!==state.unit&&weight.trim()!==''&&Number.isFinite(Number(weight))){weight=String(Math.round(Number(weight)*(next==='kg'?0.45359237:2.20462262)*10)/10);}if(save({...state,unit:next}))render();}else if(d.step){const [field,delta]=d.step.split(':');let value=Number((field==='weight'?weight:reps).trim().replace(',','.'))||0;if(field==='weight'){const m=state.machines.find(m=>m.id===selected);value=nextWeight(m,value,Number(delta)>0?1:-1);}else value=Math.max(1,value+Number(delta));if(field==='weight')weight=String(value);else reps=String(value);document.querySelector('#'+field).value=value;}else if(d.repeat){const s=state.sets.find(s=>s.id===d.repeat);weight=String(s.weight);reps=s.reps===null?'':String(s.reps);save({...state,unit:s.unit});render();toast('Numbers ready. Tap Log set to save.');}else if(d.remove){if(save({...state,sets:state.sets.filter(s=>s.id!==d.remove)})){render();toast('Set removed');}}updateLogPreview();});

root.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='edit-machine-form'){const f=new FormData(e.target);const name=String(f.get('name')||'').trim();const brand=f.get('brand');if(!name||name.length>80){toast('Enter a machine name up to 80 characters');return;}if(!['HOIST','Other'].includes(brand))return;if(state.machines.some(m=>m.id!==selected&&m.name.toLowerCase()===name.toLowerCase()&&(m.brand||'Other')===brand)){toast('That machine is already on your list');return;}if(save({...state,machines:state.machines.map(m=>m.id===selected?{...m,name,brand}:m)})){view='detail';render();window.scrollTo(0,0);toast('Machine updated');}}else if(e.target.id==='machine-form'){const f=new FormData(e.target);const name=f.get('name').trim();if(!name){toast('Enter a machine name');return;}if(state.machines.some(m=>m.name.toLowerCase()===name.toLowerCase()&&(m.brand||'Other')===(f.get('brand')||'Other'))){toast('That machine is already on your list');return;}if(save({...state,machines:[...state.machines,{id:crypto.randomUUID(),name,group:f.get('group'),brand:f.get('brand')||'Other'}]})){view='list';query='';group='All';render();toast('Machine added');}}else if(e.target.id==='set-form'){const w=Number(weight.trim().replace(',','.'));const r=reps.trim()===''?null:Number(reps);if(weight.trim()===''||!Number.isFinite(w)||w<0||w>10000){toast('Enter a weight from 0 to 10,000');return;}if(r!==null&&(!Number.isInteger(r)||r<1||r>999)){toast('Enter whole reps from 1 to 999, or leave blank');return;}const s={id:crypto.randomUUID(),machine:selected,person:state.person,weight:w,reps:r,unit:state.unit,time:new Date().toISOString()};if(save({...state,sets:[...state.sets,s]})){weight=String(w);render();toast('Set saved for '+state.person);}}});
function lastUsed(m){const ids=new Set(state.machines.filter(x=>muscleGroup(x)===muscleGroup(m)).map(x=>x.id));const times=state.sets.filter(s=>ids.has(s.machine)&&s.person===state.person).map(s=>Date.parse(s.time));return times.length?Math.max(...times):0;}
function observedWeights(m){return [...new Set(state.sets.filter(s=>s.machine===m.id).map(s=>Math.round(s.weight*(s.unit===state.unit?1:state.unit==='kg'?0.45359237:2.20462262)*10)/10))].sort((a,b)=>a-b);}
function learnedStep(m,value){const records=state.sets.filter(s=>s.machine===m.id);const counts={lb:0,kg:0};for(const s of records)counts[s.unit]++;const unit=counts.kg>counts.lb?'kg':'lb';const weights=[...new Set(records.filter(s=>s.unit===unit).map(s=>s.weight))].sort((a,b)=>a-b);const gaps=weights.slice(1).map((w,i)=>({step:Math.round((w-weights[i])*100)/100,mid:(w+weights[i])/2})).filter(g=>g.step>0);if(!gaps.length)return {step:state.unit==='kg'?2.5:5,learned:false};const freq=new Map();for(const g of gaps)freq.set(g.step,(freq.get(g.step)||0)+1);const nativeValue=value*(state.unit===unit?1:unit==='kg'?0.45359237:2.20462262);gaps.sort((a,b)=>freq.get(b.step)-freq.get(a.step)||Math.abs(a.mid-nativeValue)-Math.abs(b.mid-nativeValue)||a.step-b.step);const step=gaps[0].step*(state.unit===unit?1:state.unit==='kg'?0.45359237:2.20462262);return {step,learned:true};}
function nextWeight(m,value,direction){const choices=observedWeights(m);const known=direction>0?choices.find(w=>w>value+0.05):choices.filter(w=>w<value-0.05).at(-1);if(known!==undefined)return known;return Math.max(0,Math.min(10000,Math.round((value+direction*learnedStep(m,value).step)*10)/10));}
function weightStepHint(m){const value=Number(weight.trim().replace(',','.'))||0;const learned=learnedStep(m,value);return learned.learned?'Buttons follow logged weights; estimated next step '+Math.round(learned.step*10)/10+' '+state.unit+'. Check the machine label.':'Log different weights to teach this machine’s steps.';}
function suggestions(m){const own=machineSets().sort((a,b)=>a.time.localeCompare(b.time));const recent=own.at(-1);if(!recent)return observedWeights(m).slice(0,3);const value=Math.round(recent.weight*(recent.unit===state.unit?1:state.unit==='kg'?0.45359237:2.20462262)*10)/10;return [...new Set([nextWeight(m,value,-1),value,nextWeight(m,value,1)])].sort((a,b)=>a-b);}
function historyMarkup(sets){const old=sets.filter(s=>!isToday(s.time));const days=[...new Set(old.map(s=>localDay(s.time)))].reverse();return days.length?'<details class="history"><summary>Workout history · '+days.length+' days</summary>'+days.map(day=>{const rows=old.filter(s=>localDay(s.time)===day);return '<div class="history-day"><h3>'+esc(dateLabel(rows[0].time))+'</h3>'+rows.map(s=>'<div class="history-set">'+esc(format(s))+(s.transcriptionNote?'<small class="transcription">Notebook estimate: '+esc(s.transcriptionNote)+'</small>':'')+'</div>').join('')+'</div>';}).join('')+'</details>':'';}
function validateImport(data){if(data.version!==1||!Array.isArray(data.machines)||!Array.isArray(data.sets)||data.sets.length>10000||data.machines.length>500)throw Error('This is not a supported workout file.');const ids=new Set();for(const m of data.machines){if(typeof m.id!=='string'||ids.has(m.id)||typeof m.name!=='string'||!m.name.trim()||typeof m.group!=='string'||!['HOIST','Other'].includes(m.brand))throw Error('Invalid machine in workout file.');ids.add(m.id);}const setIds=new Set();for(const s of data.sets){if(typeof s.id!=='string'||setIds.has(s.id)||!ids.has(s.machine)||!['Justin','Mabel'].includes(s.person)||!['lb','kg'].includes(s.unit)||typeof s.weight!=='number'||!Number.isFinite(s.weight)||s.weight<0||s.weight>10000||(s.reps!==null&&(!Number.isInteger(s.reps)||s.reps<1||s.reps>999))||typeof s.time!=='string'||Number.isNaN(Date.parse(s.time)))throw Error('Invalid set in workout file.');setIds.add(s.id);}return data;}
function mergeImport(data){validateImport(data);const machines=[...state.machines],map=new Map();for(const m of data.machines){const existing=machines.find(x=>x.name.toLowerCase()===m.name.toLowerCase()&&(x.brand||'Other')===m.brand);if(existing)map.set(m.id,existing.id);else{const id=machines.some(x=>x.id===m.id)?'notebook-'+m.id:m.id;if(machines.some(x=>x.id===id))throw Error('Machine ID conflict.');machines.push({...m,id});map.set(m.id,id);}}const ids=new Set(state.sets.map(s=>s.id));const incoming=data.sets.filter(s=>!ids.has(s.id)).map(s=>({...s,machine:map.get(s.machine)}));const next={...state,machines,sets:[...state.sets,...incoming].sort((a,b)=>a.time.localeCompare(b.time))};if(!save(next))throw Error('Nothing imported. Local storage is unavailable.');return incoming.length;}
root.addEventListener('change',async e=>{if(e.target.id!=='import-file'||!e.target.files[0])return;const file=e.target.files[0];const status=document.querySelector('#import-status');try{if(file.size>3000000)throw Error('File is too large.');const data=JSON.parse(await file.text());const count=mergeImport(data);status.textContent=count+' sets imported. '+(data.omitted?.length?data.omitted.length+' unclear notebook entries were left out.':'');toast(count?'Notebook imported':'Already imported; no duplicates added');}catch(err){status.textContent=err.message;}});

if(!storageError&&state.defaultsVersion!==1){if(!state.sets.length){try{mergeImport(defaultNotebook);}catch(e){storageError=e.message;}}if(!storageError)save({...state,defaultsVersion:1});}
render();
if('serviceWorker' in navigator){navigator.serviceWorker.register('./sw.js?v=9', {updateViaCache:'none'}).then(()=>navigator.serviceWorker.ready).then(()=>{offlineReady=true;const f=document.querySelector('.foot span:last-child');if(f)f.textContent='Ready offline · Saved on this device';const info=document.querySelector('#offline-info');if(info)info.textContent='Ready to use offline.';}).catch(()=>{const info=document.querySelector('#offline-info');if(info)info.textContent='Offline setup failed. Reopen the app while online to try again.';});}
